    const trialId = fs.readFileSync("/logs/trial_id", "utf-8").trim();
    const channelName = `summary-${trialId}`;
    const userId = "zealt-user01";

    const openai = new OpenAI();
    const composio = new Composio({
        provider: new OpenAIProvider(),
    });

    const tools = await composio.tools.get(userId, {
        toolkits: ['gmail', 'slack'],
    });

    console.log("Got tools, trying to execute one with userId...");
    // Just a test to see if it accepts userId
    try {
        // @ts-ignore
        await composio.provider.executeToolCall({ id: "test", function: { name: "test", arguments: "{}" } }, userId);
        console.log("Accepted (toolCall, userId)");
    } catch (e) {
        console.log("Failed (toolCall, userId)");
