    try {
        // @ts-ignore
        await composio.provider.executeToolCall(userId, { id: "test", function: { name: "test", arguments: "{}" } });
        console.log("Accepted (userId, toolCall)");
    } catch (e) {
        console.log("Failed (userId, toolCall)");
    }
}

