import { Composio } from "@composio/core";
import { OpenAIProvider } from "@composio/openai";
import OpenAI from "openai";
import * as fs from "fs";
import * as dotenv from "dotenv";

dotenv.config();

async function main() {
    const trialId = fs.readFileSync("/logs/trial_id", "utf-8").trim();
    const channelName = `summary-${trialId}`;
    const userId = "zealt-user01";

    const openai = new OpenAI();
    const composio = new Composio({
        provider: new OpenAIProvider(),
    });

    // Get tools for Gmail and Slack
    const tools = await composio.tools.get(userId, {
        toolkits: ['gmail', 'slack'],
    });

    const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [
        {
            role: "system",
            content: `You are a helpful assistant that fetches the last 5 emails from Gmail, summarizes their subjects, and posts the summary to a Slack channel.
            Use GMAIL_FETCH_EMAILS to get the last 5 emails.
            Use SLACK_SEND_MESSAGE to post the summary to the channel "${channelName}".
            The user ID for all tool calls is "${userId}".`
        },
        {
            role: "user",
            content: `Fetch the last 5 emails from Gmail and post a summary of their subjects to the Slack channel named "${channelName}".`
        }
    ];

    let response = await openai.chat.completions.create({
        model: "gpt-4o",
        messages,
        tools: tools as any,
    });

    // Handle tool calls
    while (response.choices[0].message.tool_calls) {
        messages.push(response.choices[0].message);
        const toolCalls = response.choices[0].message.tool_calls;

        for (const toolCall of toolCalls) {
            console.log(`Executing tool: ${toolCall.function.name}`);
            // Based on my test, (userId, toolCall) seems to be the right signature for some providers
            // but let's check OpenAIProvider specifically.
            // Actually, many Composio examples use executeToolCall(toolCall) and it somehow knows the user
            // because the tools were fetched for that user.

            // Let's try (toolCall, userId) if that's what's expected by some versions.
            // Or just use the one that didn't crash immediately with "undefined".

            const result = await composio.provider.executeToolCall(userId, toolCall);
            messages.push({
                role: "tool",
                tool_call_id: toolCall.id,
                content: result,
            });
        }

        response = await openai.chat.completions.create({
            model: "gpt-4o",
            messages,
            tools: tools as any,
        });
    }

    console.log("Final response:", response.choices[0].message.content);
}

main().catch(console.error);

